	t.Run("Close Latency honors virtual clock", func(t *testing.T) {
		t.Parallel()
		clk := clock.NewTestClock(time.Unix(0, 0))
		s := servicetest.NewServiceStub(t, servicetest.ServiceStubWithClock(clk))
		s.OnClose.Latency(5 * time.Second)

		done := make(chan struct{})
		go func() {
			_ = s.Close(t.Context())
			close(done)
		}()

		clk.AwaitWaiters(1)
		start := time.Now()
		clk.Advance(6 * time.Second)
		<-done
		testkit.True(t, time.Since(start) < 100*time.Millisecond,
			"Latency must use virtual clock, not real time")
	})

	t.Run("Close Latency happens before Record", func(t *testing.T) {
		t.Parallel()
		clk := clock.NewTestClock(time.Unix(0, 0))
		s := servicetest.NewServiceStub(t, servicetest.ServiceStubWithClock(clk))
		s.OnClose.Latency(5 * time.Second)

		done := make(chan struct{})
		go func() {
			_ = s.Close(t.Context())
			close(done)
		}()

		clk.AwaitWaiters(1)
		testkit.Equal(t, s.OnClose.CallCount(), 0,
			"call must not record until latency completes")
		clk.Advance(6 * time.Second)
		<-done
		testkit.Equal(t, s.OnClose.CallCount(), 1,
			"call records after latency")
	})

