		inner.OnPut.Returns(nil)
		s := servicetest.NewServiceStub(t,
			servicetest.ServiceStubWithClock(clk),
			servicetest.ServiceStubDelegateTo(inner))
		s.OnClose.Latency(5 * time.Second)

		done := make(chan struct{})
		go func() {
			_ = s.Close(t.Context())
			close(done)
		}()

		clk.AwaitWaiters(1)
		start := time.Now()
